import java.util.*;
import course.examples.objects.Book;
/** Только предъявление двух опубликованных сценариев. Решение и исходник принимает преподаватель. */
public class PublicChecks {
 public record Observation(String actual) {}
 public static void main(String[] args){try{System.out.println("PUBLIC normal | Владелец Java, затем Types; ожидаются размеры 2/2/1/1, общая выданная книга, запрет add через view/snapshot | ФАКТИЧЕСКИ: "+observeNormal().actual()+" | СТАТУС: предъявить преподавателю");System.out.println("PUBLIC boundary | Пустой вход; внешнее добавление не видно; затем владелец дважды добавляет одну книгу, только старый view видит обе ссылки | ФАКТИЧЕСКИ: "+observeBoundary().actual()+" | СТАТУС: предъявить преподавателю");}catch(Throwable e){System.err.println("Предъявление не завершено: сбой вызова; нужна проверка решения или привязки преподавателем.");System.exit(2);}}

 private static String composition(List<Book> books){return books.stream().map(Book::title).toList().toString();}
 private static boolean rejected(List<Book> list,Book book){try{list.add(book);return false;}catch(UnsupportedOperationException expected){return true;}}
 public static Observation observeNormal(){Book first=new Book("Java");Object owner=TaskBinding.owner(new ArrayList<>(List.of(first)));var v=TaskBinding.view(owner);var c=TaskBinding.copy(owner);var s=TaskBinding.snapshot(owner);TaskBinding.add(owner,new Book("Types"));first.borrow();boolean shared=TaskBinding.view(owner).get(0)==first&&v.get(0)==first&&c.get(0)==first&&s.get(0)==first;return new Observation("размеры="+TaskBinding.view(owner).size()+"/"+v.size()+"/"+c.size()+"/"+s.size()+"; общая ссылка="+shared+"; выдача="+TaskBinding.view(owner).get(0).borrowed()+"/"+v.get(0).borrowed()+"/"+c.get(0).borrowed()+"/"+s.get(0).borrowed()+"; add view отклонён="+rejected(v,new Book("Проверка view"))+"; add snapshot отклонён="+rejected(s,new Book("Проверка snapshot"))+"; составы после отказов="+composition(TaskBinding.view(owner))+"/"+composition(v)+"/"+composition(c)+"/"+composition(s));}
 public static Observation observeBoundary(){var input=new ArrayList<Book>();Object owner=TaskBinding.owner(input);var v=TaskBinding.view(owner);var c=TaskBinding.copy(owner);var s=TaskBinding.snapshot(owner);input.add(new Book("Вход"));String afterInput=TaskBinding.view(owner).size()+"/"+v.size()+"/"+c.size()+"/"+s.size();Book shared=new Book("Общая");TaskBinding.add(owner,shared);TaskBinding.add(owner,shared);boolean twice= v.size()==2&&v.get(0)==shared&&v.get(1)==shared;return new Observation("после изменения входа="+afterInput+"; после владельца="+TaskBinding.view(owner).size()+"/"+v.size()+"/"+c.size()+"/"+s.size()+"; две исходные одинаковые ссылки view="+twice+"; те же ссылки владельца="+(TaskBinding.view(owner).size()==2&&TaskBinding.view(owner).get(0)==shared&&TaskBinding.view(owner).get(1)==shared));}

}
